          (WORD32 *)ixheaacd_ldmps_polyphase_filter_coeff_fix;
  }

  ptr_sbr_qmf->no_channels = NO_ANALYSIS_CHANNELS;
  if (no_ldsbr) ptr_sbr_qmf->no_channels = 64;
